{source="Assets/_Project/Resources/ArtExtra/tea_sommelier_bow_ready/bow_ranged_right_03.png", target="Assets/_Project/Resources/CosmeticSkins/skin_tea_jade/bow_ranged_right_03.png", skin="skin_tea_jade"},
