for _, job in ipairs(jobs) do
 local s=app.open(job.source)
 local im=s.cels[1].image
 for y=math.floor(im.height*.35),im.height-1 do
  for x=0,im.width-1 do
   local p=im:getPixel(x,y)
   local a=app.pixelColor.rgbaA(p)
   local r=app.pixelColor.rgbaR(p)
   local g=app.pixelColor.rgbaG(p)
   local b=app.pixelColor.rgbaB(p)
   if a>0 and r<145 and g<120 and b<105 and r>=g and g>=b then
    local l=(r+g+b)/3
    if job.skin=='skin_tea_jade' then
     im:drawPixel(x,y,app.pixelColor.rgba(math.floor(l*.55),math.floor(l*1.05+12),math.floor(l*.7+8),a))
    else
     im:drawPixel(x,y,app.pixelColor.rgba(math.floor(l*.55),math.floor(l*.75+8),math.floor(l*1.12+16),a))
    end
   end
  end
 end
 im:saveAs(job.target)
 s:close()
end
